	}

	/* @Test */
	public void testTypeToSignature()
    {
		Map<string, string> signatures = new();
		string internalName =
			typeof(HasFieldTypeSignatures).getName().replace('.', '/') + ".class";
		byte[] bytes;
		using (InputStream @is = getClass().getClassLoader().getResourceAsStream(internalName))
{
			bytes = @is.readAllBytes();
		}
		ClassModel cm = ClassFile.of().parse(bytes);
		foreach (FieldModel fm in cm.fields()) {
			string signature = fm.findAttribute(
				Attributes.signature())
					.map(sa => sa.signature().stringValue())
					.orElse(null);
			signatures.put(fm.fieldName().stringValue(), signature);
		}

		assertEquals(signatures.get("RECS"), JitJvmTypeUtils
				.typeToSignature(new TypeLiteral<List<AddrCtx>>() {}.value));
		assertEquals(signatures.get("WILDS"), JitJvmTypeUtils
				.typeToSignature(new TypeLiteral<List<object>>() {}.value));
		assertEquals(signatures.get("SUPERS"), JitJvmTypeUtils
				.typeToSignature(new TypeLiteral<List<AddrCtx>>() {}.value));
		assertEquals(signatures.get("EXTENDS"), JitJvmTypeUtils
				.typeToSignature(new TypeLiteral<List<AddrCtx>>() {}.value));
	}
